SELECT id, log_ts, latency_ms, context, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').retries AS retry_count, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').user.tier AS tier, ARRAY_CONTAINS(MAP_KEYS(context), 'region') AS has_region, SIZE(context) AS num_context FROM app_logs WHERE latency_ms <= 2248;
